/* the behaviour of a site generated by "isabelle site": the reader profile and navigation */
(function () {
  'use strict';

  var KEY = 'site.profile';
  var profile = null;
  var shown = location.pathname;


  function axes() {
    var a = document.body.getAttribute('data-axes');
    return a ? a.split(',') : [];
  }

  function levels() {
    var l = document.body.getAttribute('data-levels');
    return l ? l.split(',').map(Number) : [];
  }

  function rendered() {
    return document.body.getAttribute('data-profile') || 'none';
  }

  function form() { return document.querySelector('.profile-form'); }


  /* profiles */

  function fromQuery(search) {
    var params = new URLSearchParams(search), names = axes(), counts = levels(), p = {}, i;
    if (!names.length) return null;
    for (i = 0; i < names.length; i++) {
      var v = params.get(names[i]);
      if (v === null || !/^\d+$/.test(v) || Number(v) >= counts[i]) return null;
      p[names[i]] = Number(v);
    }
    return p;
  }

  function query(p) {
    return p ? axes().map(function (a) { return a + '=' + p[a]; }).join('&') : '';
  }

  function save(p) {
    try {
      if (p) localStorage.setItem(KEY, query(p)); else localStorage.removeItem(KEY);
    } catch (e) { /* no storage available: the profile lives in the URL only */ }
  }

  function stored() {
    try { return fromQuery(localStorage.getItem(KEY) || ''); } catch (e) { return null; }
  }

  function of_page() {         /* the profile this page was pre-rendered for, if any */
    return fromQuery(document.body.getAttribute('data-profile-query') || '');
  }

  /* audience predicates */

  function holds(pred, p) {
    return pred.split('|').some(function (conj) {
      return conj.trim().split(/\s+/).every(function (atom) {
        var m = /^([A-Za-z0-9_]+)(>=|<=|!=|=)(\d+)$/.exec(atom);
        if (!m) return false;
        var v = p[m[1]], n = Number(m[3]);
        if (v === undefined) return false;
        return m[2] === '=' ? v === n : m[2] === '!=' ? v !== n : m[2] === '>=' ? v >= n : v <= n;
      });
    });
  }

  /* rendering the page for the profile */

  function render_blocks() {
    if (!profile && rendered() === 'all') return;
    Array.prototype.forEach.call(document.querySelectorAll('[data-audience]'), function (d) {
      d.hidden = !(profile && holds(d.getAttribute('data-audience'), profile));
    });
  }

  function render_links() {
    var q = query(profile);
    Array.prototype.forEach.call(document.querySelectorAll('a[href]'), function (a) {
      var href = a.getAttribute('href');
      if (/^([a-z]+:|#|\/)/i.test(href)) return;
      var hash = href.indexOf('#'), anchor = hash < 0 ? '' : href.slice(hash);
      var path = (hash < 0 ? href : href.slice(0, hash)).split('?')[0];
      if (!/\.html$/.test(path)) return;
      a.setAttribute('href', path + (q ? '?' + q : '') + anchor);
    });
  }

  function render_url() {
    var q = query(profile);
    history.replaceState(history.state, '',
      location.pathname + (q ? '?' + q : '') + location.hash);
  }

  function tags() {
    if (!profile) return [];
    var t;
    try { t = JSON.parse(document.body.getAttribute('data-tags') || '[]'); } catch (e) { t = []; }
    return axes().map(function (a, i) { return (t[i] || [])[profile[a]] || ''; })
      .filter(function (x) { return x; });
  }

  function render_control() {
    var f = form(), summary = document.querySelector('.profile-current');
    if (f) {
      axes().forEach(function (a) {
        if (f.elements[a]) f.elements[a].value = profile ? String(profile[a]) : '0';
      });
    }
    if (summary) {
      var t = tags(), empty = !t.length;
      if (empty) t = [!profile && rendered() === 'all' ? 'everything' : 'none'];
      summary.textContent = '';
      t.forEach(function (x) {
        var c = document.createElement('span');
        c.className = empty ? 'tag empty' : 'tag';
        c.textContent = x;
        summary.appendChild(c);
      });
    }
  }

  function render_to_top() {
    var a = document.querySelector('.to-top');
    if (a) a.hidden = (window.scrollY || window.pageYOffset || 0) < 400;
  }

  /* the graph of the statistics page */

  var ZOOM_MS = 350, FADE_MS = 150;

  function graph_frame() { return document.querySelector('.graph-frame'); }

  function graph_box(frame, hash) {
    var id = hash ? decodeURIComponent(hash.slice(1)) : '';
    var box = id ? document.getElementById(id) : null;
    return box && box.parentNode === frame && box.classList.contains('graph-session') ? box : null;
  }

  function graph_overview(frame) { return frame.querySelector('.graph-overview'); }

  function graph_node(frame, box) {
    var o = graph_overview(frame), transform = o.style.transform;
    o.style.transform = '';
    var rect = o.querySelector('a[href="#' + box.id + '"] rect');
    var f = frame.getBoundingClientRect();
    var r = rect ? rect.getBoundingClientRect()
      : { left: f.left + f.width / 2, top: f.top + f.height / 2, width: 0, height: 0 };
    o.style.transform = transform;
    return { left: r.left - f.left, top: r.top - f.top, width: r.width, height: r.height };
  }

  function graph_place(box, r) {
    box.style.left = r ? r.left + 'px' : '';
    box.style.top = r ? r.top + 'px' : '';
    box.style.width = r ? r.width + 'px' : '';
    box.style.height = r ? r.height + 'px' : '';
  }

  function graph_zoom(frame, r) {
    var o = graph_overview(frame);
    if (r) {
      var scale = Math.min(frame.clientWidth / Math.max(r.width, 1), frame.clientHeight / Math.max(r.height, 1));
      o.style.transformOrigin = (r.left + r.width / 2) + 'px ' + (r.top + r.height / 2) + 'px';
      o.style.transform = 'scale(' + scale + ')';
      o.style.opacity = '0';
    }
    else { o.style.transform = ''; o.style.opacity = ''; o.style.visibility = ''; }
  }

  function graph_later(frame, ms, f) {
    var t = setTimeout(function () {
      frame.graph_timers = frame.graph_timers.filter(function (u) { return u !== t; });
      f();
    }, ms);
    frame.graph_timers.push(t);
  }

  function graph_open(frame, box, animate) {
    var r = graph_node(frame, box);
    box.hidden = false;
    if (!animate) {
      graph_zoom(frame, r);
      graph_overview(frame).style.visibility = 'hidden';
      return;
    }
    box.classList.add('closed');
    graph_place(box, r);
    void box.offsetWidth;             /* lay out at the node's size, where the transition starts */
    frame.classList.add('zoom');
    graph_place(box, null);
    graph_zoom(frame, r);
    graph_later(frame, ZOOM_MS, function () {
      frame.classList.remove('zoom');
      box.classList.remove('closed');
      graph_overview(frame).style.visibility = 'hidden';
    });
  }

  function graph_close(frame, box, animate) {
    var r = graph_node(frame, box);
    graph_overview(frame).style.visibility = '';
    if (!animate) {
      box.hidden = true;
      box.classList.remove('closed');
      graph_place(box, null);
      graph_zoom(frame, null);
      return;
    }
    box.classList.add('closed');
    graph_later(frame, FADE_MS, function () {
      frame.classList.add('zoom');
      graph_place(box, r);
      graph_zoom(frame, null);
      graph_later(frame, ZOOM_MS, function () {
        frame.classList.remove('zoom');
        box.hidden = true;
        box.classList.remove('closed');
        graph_place(box, null);
      });
    });
  }

  function graph_tables(box) {
    var stats = document.querySelector('.session-stats');
    if (!stats) return;
    stats.classList.toggle('focused', !!box);
    Array.prototype.forEach.call(stats.querySelectorAll('.session-stat'), function (s) {
      s.classList.toggle('shown', !!box && s.getAttribute('data-graph') === box.id);
    });
  }

  function graph_show(frame, hash, animate) {
    var busy = frame.graph_timers.length > 0;
    frame.graph_timers.forEach(clearTimeout);
    frame.graph_timers = [];
    frame.classList.remove('zoom');
    var want = graph_box(frame, hash);
    graph_tables(want);
    var open = Array.prototype.filter.call(frame.querySelectorAll('.graph-session'),
      function (b) { return !b.hidden; });
    if (busy) {
      open.forEach(function (b) { graph_close(frame, b, false); });
      open = [];
      animate = false;
    }
    if (open.length === 1 && open[0] === want) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) animate = false;
    if (want) {
      open.forEach(function (b) { graph_close(frame, b, false); });
      graph_open(frame, want, animate);
    }
    else open.forEach(function (b) { graph_close(frame, b, animate); });
  }

  function render_graph() {
    var frame = graph_frame();
    if (!frame || frame.classList.contains('js')) return;
    frame.classList.add('js');
    frame.graph_timers = [];
    Array.prototype.forEach.call(frame.querySelectorAll('.graph-session'), function (b) { b.hidden = true; });
    graph_show(frame, location.hash, false);
  }

  function render() {
    render_blocks();
    render_graph();
    render_links();
    render_url();
    render_control();
    render_to_top();
    /* the hook for a site's own scripts, after a profile change or a page swap */
    document.dispatchEvent(new CustomEvent('site:render', { detail: { profile: profile } }));
  }

  function set(p) {
    profile = p;
    save(p);
    render();
  }

  /* the header control */

  function bind() {
    var f = form(), links = document.querySelector('.profile-links');
    if (!f) return;
    f.hidden = false;                     /* with the script, the dials replace the links */
    if (links) links.hidden = true;
    f.addEventListener('change', function () {
      var p = {}, names = axes();
      names.forEach(function (a) { p[a] = profile && profile[a] !== undefined ? profile[a] : 0; });
      names.forEach(function (a) { if (f.elements[a]) p[a] = Number(f.elements[a].value); });
      set(p);
    });
    var reset = f.querySelector('.profile-reset');
    if (reset) reset.addEventListener('click', function () { set(null); });
  }

  /* same-page navigation */

  function dir(path) { return path.slice(0, path.lastIndexOf('/') + 1); }

  /* a page of this site shares its directory; the theories under src/ are not ours */
  function ours(a) {
    if (a.target || a.hasAttribute('download') || a.classList.contains('external')) return false;
    var href = a.getAttribute('href') || '';
    if (/^([a-z]+:|#)/i.test(href)) return false;
    if (a.origin !== location.origin || !/\.html$/.test(a.pathname)) return false;
    return dir(a.pathname) === dir(location.pathname);
  }

  function become(doc) {
    if (!doc.querySelector('main#main')) throw new Error('not a page of this site');
    var title = doc.querySelector('title');
    if (title) document.title = title.textContent;
    var attrs = document.body.attributes, i;
    for (i = attrs.length - 1; i >= 0; i--) document.body.removeAttribute(attrs[i].name);
    for (i = 0; i < doc.body.attributes.length; i++) {
      document.body.setAttribute(doc.body.attributes[i].name, doc.body.attributes[i].value);
    }
    document.body.innerHTML = doc.body.innerHTML;
    bind();
    render();
  }

  var going = 0;

  function go(url, push) {
    var n = ++going;
    return fetch(url, { credentials: 'same-origin' })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); })
      .then(function (html) {
        if (n !== going) return;          /* a later navigation overtook this one */
        var doc = new DOMParser().parseFromString(html, 'text/html');
        var y = push ? null : history.state && history.state.y;
        if (push) {
          history.replaceState({ y: window.scrollY }, '');   /* where Back returns to */
          history.pushState(null, '', url);
        }
        try { become(doc); shown = location.pathname; }
        catch (e) { if (push) history.back(); throw e; }
        /* by id, not selector: an entity's id has dots in it */
        var hash = new URL(url, location.href).hash;
        var target = hash && document.getElementById(decodeURIComponent(hash.slice(1)));
        if (typeof y === 'number') window.scrollTo(0, y);
        else if (target) target.scrollIntoView();
        else window.scrollTo(0, 0);
        var main = document.querySelector('main#main');
        if (main && main.hasAttribute('tabindex')) main.focus({ preventScroll: true });
      });
  }

  function navigable() {
    return !!(window.history && window.history.pushState && window.fetch && window.DOMParser);
  }

  function init() {
    profile = new URLSearchParams(location.search).has('none') ? null
      : fromQuery(location.search) || stored() || of_page();
    save(profile);
    bind();
    render();
    window.addEventListener('scroll', render_to_top, { passive: true });

    /* looked up at the event, since a page swap replaces the control */
    function control() { return document.querySelector('details.profile'); }
    document.addEventListener('click', function (e) {
      var d = control();
      if (d && d.open && !d.contains(e.target)) d.open = false;
    });
    document.addEventListener('keydown', function (e) {
      var d = control();
      if (e.key === 'Escape' && d && d.open) { d.open = false; d.querySelector('summary').focus(); }
    });

    document.addEventListener('click', function (e) {
      if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      var a = e.target.closest && e.target.closest('a[href^="#graph-"]');
      var frame = graph_frame();
      if (!a || !frame || !frame.classList.contains('js') || !frame.contains(a)) return;
      e.preventDefault();
      var hash = graph_box(frame, a.getAttribute('href')) ? a.getAttribute('href') : '';
      if (hash !== location.hash && window.history && history.pushState)
        history.pushState(history.state, '', location.pathname + location.search + hash);
      graph_show(frame, hash, true);
    });
    window.addEventListener('popstate', function () {
      var frame = graph_frame();
      if (frame && frame.classList.contains('js')) graph_show(frame, location.hash, true);
    });

    if (!navigable()) return;
    document.addEventListener('click', function (e) {
      if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      var a = e.target.closest && e.target.closest('a[href]');
      if (!a || !ours(a)) return;
      e.preventDefault();
      go(a.href, true).catch(function () { location.href = a.href; });
    });
    window.addEventListener('popstate', function () {
      if (location.pathname === shown) return;      /* a move within the page: its fragment */
      go(location.href, false).catch(function () { location.reload(); });
    });
  }

  window.Site = { profile: function () { return profile; }, set: set, axes: axes };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
